CREATE TABLE quiz_result (
    result_id              SERIAL PRIMARY KEY,
    explanation            TEXT,
    created_at             TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    user_id                INTEGER NOT NULL,
    total_question         SMALLINT,
    corrected_answer_num   SMALLINT,
    score_percent          INTEGER GENERATED ALWAYS AS (
        CASE 
            WHEN total_question > 0 
            THEN ROUND(100.0 * corrected_answer_num / total_question)::INTEGER
            ELSE 0 
        END
    ) STORED,
    completion_status      CHAR(20) DEFAULT 'not_completed',
    topic_id               INTEGER NOT NULL
);

