-- =============================================================================
-- AUTO-CALCULATION FUNCTIONS FOR QUIZ_RESULT
-- =============================================================================

-- Function to auto-calculate total_question and explanation when quiz is completed
CREATE OR REPLACE FUNCTION update_quiz_result_auto_fields()
RETURNS TRIGGER AS $$
BEGIN
    -- Only calculate when completion_status changes to 'completed'
    IF NEW.completion_status = 'completed' AND OLD.completion_status != 'completed' THEN
        
        -- Auto-calculate total_question
        NEW.total_question := (
            SELECT COUNT(DISTINCT qa.selected_option_id)
            FROM quiz_answer qa 
            WHERE qa.result_id = NEW.result_id 
            AND qa.user_id = NEW.user_id
        );
        
        -- Auto-calculate corrected_answer_num
        NEW.corrected_answer_num := (
            SELECT COUNT(*)
            FROM quiz_answer qa 
            WHERE qa.result_id = NEW.result_id 
            AND qa.user_id = NEW.user_id 
            AND qa.is_correct = 'True'
        );
        
        -- Auto-generate explanation for wrong answers
        NEW.explanation := (
            SELECT COALESCE(
                STRING_AGG(DISTINCT rls.legal_content_plain_en, E'\n\n---\n\n'), 
                'All answers correct! No legal violations found.'
            )
            FROM quiz_answer qa
            JOIN quiz_option qo ON qa.selected_option_id = qo.option_id
            JOIN quiz_question qq ON qo.question_id = qq.question_id
            JOIN legal_topic_mapping ltm ON qq.legal_topic_mapping_id = ltm.legal_topic_mapping_id
            JOIN ref_legal_section rls ON ltm.legal_id = rls.legal_id 
                AND ltm.language_code = rls.language_code 
                AND ltm.source_id = rls.source_id
            JOIN "user" u ON qa.user_id = u.user_id
            WHERE qa.result_id = NEW.result_id 
            AND qa.user_id = NEW.user_id
            AND qa.is_correct = 'False'
            AND rls.language_code = COALESCE(u.language_code, 'EN')
        );
        
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create trigger to auto-calculate fields when quiz is completed
CREATE TRIGGER quiz_result_auto_calculate
    BEFORE UPDATE ON quiz_result
    FOR EACH ROW
    EXECUTE FUNCTION update_quiz_result_auto_fields();

-- =============================================================================
-- HELPER FUNCTION FOR MANUAL CALCULATION (if needed)
-- =============================================================================

-- Function to manually recalculate quiz result fields
CREATE OR REPLACE FUNCTION recalculate_quiz_result(
    p_result_id BIGINT,
    p_user_id INTEGER
) RETURNS VOID AS $$
BEGIN
    UPDATE quiz_result 
    SET 
        total_question = (
            SELECT COUNT(DISTINCT qa.selected_option_id)
            FROM quiz_answer qa 
            WHERE qa.result_id = p_result_id 
            AND qa.user_id = p_user_id
        ),
        corrected_answer_num = (
            SELECT COUNT(*)
            FROM quiz_answer qa 
            WHERE qa.result_id = p_result_id 
            AND qa.user_id = p_user_id 
            AND qa.is_correct = 'True'
        ),
        explanation = (
            SELECT COALESCE(
                STRING_AGG(DISTINCT rls.legal_content_plain_en, E'\n\n---\n\n'), 
                'All answers correct! No legal violations found.'
            )
            FROM quiz_answer qa
            JOIN quiz_option qo ON qa.selected_option_id = qo.option_id
            JOIN quiz_question qq ON qo.question_id = qq.question_id
            JOIN legal_topic_mapping ltm ON qq.legal_topic_mapping_id = ltm.legal_topic_mapping_id
            JOIN ref_legal_section rls ON ltm.legal_id = rls.legal_id 
                AND ltm.language_code = rls.language_code 
                AND ltm.source_id = rls.source_id
            JOIN "user" u ON qa.user_id = u.user_id
            WHERE qa.result_id = p_result_id 
            AND qa.user_id = p_user_id
            AND qa.is_correct = 'False'
            AND rls.language_code = COALESCE(u.language_code, 'EN')
        )
    WHERE result_id = p_result_id AND user_id = p_user_id;


END;
$$ LANGUAGE plpgsql;

